import java.io.File;
import java.nio.file.Path;
import java.nio.file.Paths;

public class ImportingUtilities {

    // other methods

    /**
     * Creates a new {@link File} inside {@code dir} with the given {@code name}.
     * The method protects against directory‑traversal attacks by normalizing the
     * resolved path and ensuring it stays within {@code dir}. It also removes
     * any query string from {@code name} and guarantees that the resulting
     * file does not already exist by appending a numeric suffix if needed.
     *
     * @param dir  the base directory where the file should be created; must not be {@code null}
     * @param name the desired file name; must not be {@code null}
     * @return a {@link File} instance pointing to a unique file inside {@code dir}
     * @throws IllegalArgumentException if {@code dir} or {@code name} is {@code null},
     *                                  or if the resolved path would escape {@code dir}
     */
    static public File allocateFile(File dir, String name) {
        if (dir == null) {
            throw new IllegalArgumentException("Directory cannot be null");
        }
        if (name == null) {
            throw new IllegalArgumentException("File name cannot be null");
        }

        // Strip query parameters (e.g., "?foo=bar")
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Resolve and normalize the target path
        Path dirPath = dir.toPath().normalize();
        Path targetPath = dirPath.resolve(name).normalize();

        // Ensure the target path is still inside the base directory
        if (!targetPath.startsWith(dirPath)) {
            throw new IllegalArgumentException(
                "File name escapes the target directory: " + name);
        }

        File file = targetPath.toFile();

        // Split the name into prefix and suffix for generating unique names
        int dot = name.indexOf('.');
        String prefix = dot < 0 ? name : name.substring(0, dot);
        String suffix = dot < 0 ? "" : name.substring(dot);

        int index = 2;
        while (file.exists()) {
            // Append a numeric suffix until we find a non‑existing file
            file = new File(dir, prefix + "-" + index++ + suffix);
        }

        // Create any missing parent directories
        File parent = file.getParentFile();
        if (parent != null && !parent.exists()) {
            parent.mkdirs();
        }

        return file;
    }

    // other methods
}
```

