            }

            // Normalise the path to collapse '.' and '..' components
            Path entryPath = Paths.get(rawName).normalize();

            // After normalisation the path must still be relative and must not start with '..'
            if (entryPath.isAbsolute() || entryPath.startsWith("..")) {
                throw new IOException("Entry name contains path traversal: " + rawName);
            }

            // ---- 2️⃣ Construct the destination file and verify containment  ------------------
            File destFile = new File(targetDirectory, entryPath.toString());
            String destCanonical = destFile.getCanonicalPath();

            if (!destCanonical.startsWith(targetDirCanonical)) {
                throw new IOException("Expanding " + rawName + " would create file outside of "
                        + targetDirectory.getAbsolutePath());
            }

            // ---- 3️⃣ Handle directories -------------------------------------------------------
            if (nextEntry.isDirectory()) {
                if (!destFile.isDirectory() && !destFile.mkdirs()) {
                    throw new IOException("Failed to create directory " + destFile);
                }
