public class XmlImporter extends TreeImportingParserBase {

    // other methods

    /**
     * Creates a secure {@link XMLStreamReader} that is protected against XXE attacks.
     *
     * <p>The method configures the {@link XMLInputFactory} to:
     * <ul>
     *   <li>Disable DTD support ({@code SUPPORT_DTD = false})</li>
     *   <li>Disallow external entity resolution ({@code IS_SUPPORTING_EXTERNAL_ENTITIES = false})</li>
     *   <li>Enable namespace awareness for proper XML parsing</li>
     *   <li>Coalesce adjacent character data and replace entity references to simplify downstream handling</li>
     * </ul>
     * It also validates that the supplied {@code InputStream} is non‑null to avoid
     * ambiguous {@code NullPointerException}s during parsing.
     *
     * @param inputStream the XML source stream
     * @return a configured {@link XMLStreamReader}
     * @throws XMLStreamException if the XML cannot be parsed
     * @throws IOException if an I/O error occurs while reading the stream
     */
    final static private XMLStreamReader createXMLStreamReader(InputStream inputStream)
            throws XMLStreamException, IOException {

        if (inputStream == null) {
            throw new IllegalArgumentException("inputStream cannot be null");
        }

        XMLInputFactory factory = XMLInputFactory.newInstance();

        // Basic stream handling
        factory.setProperty(XMLInputFactory.IS_COALESCING, true);
        factory.setProperty(XMLInputFactory.IS_REPLACING_ENTITY_REFERENCES, true);

        // Security hardening – prevent XXE
        factory.setProperty(XMLInputFactory.SUPPORT_DTD, false);
        factory.setProperty(XMLInputFactory.IS_SUPPORTING_EXTERNAL_ENTITIES, false);

        // Enable namespace support for well‑formed XML
        factory.setProperty(XMLInputFactory.IS_NAMESPACE_AWARE, true);

        return factory.createXMLStreamReader(wrapPrefixRemovingInputStream(inputStream));
    }

    // other methods

}
