import javax.servlet.http.HttpServletRequest;
import java.io.IOException;
import java.util.Objects;

public class ScimUserSelfUpdateAllowed {

    public static final int USER_ID_PATH_PARAMETER_INDEX = 1;
    private ScimUserProvisioning scimUserProvisioning;

    // other methods

    /**
     * Determines whether the current request is allowed to update the SCIM user identified by the
     * path parameter. The method now enforces that the authenticated user is the owner of the
     * account being updated. It also performs defensive null checks and uses {@link Objects#equals}
     * for safe comparisons.
     *
     * @param request the HTTP request containing the update payload
     * @return {@code true} if the request is allowed, {@code false} otherwise
     * @throws IOException if an I/O error occurs while reading the request body
     */
    public boolean isAllowed(HttpServletRequest request) throws IOException {

        // 1. Extract the authenticated user id from the request principal.
        //    If the principal is missing, deny the request.
        String authenticatedUserId = null;
        if (request.getUserPrincipal() != null) {
            authenticatedUserId = request.getUserPrincipal().getName();
        }
        if (!Objects.equals(authenticatedUserId, UaaUrlUtils.extractPathVariableFromUrl(
                USER_ID_PATH_PARAMETER_INDEX, UaaUrlUtils.getRequestPath(request)))) {
            // The authenticated user is not the owner of the account being updated.
            return false;
        }

        // 2. Read and parse the request body into a ScimUser instance.
        String requestBody = IOUtils.toString(request.getReader());
        ScimUser scimUserFromRequest;
        try {
            scimUserFromRequest = JsonUtils.readValue(requestBody, ScimUser.class);
        } catch (Exception e) {
            // Malformed JSON or other parsing error – deny the request.
            return false;
        }

        // 3. Retrieve the current user record from the database.
        String id = UaaUrlUtils.extractPathVariableFromUrl(
                USER_ID_PATH_PARAMETER_INDEX, UaaUrlUtils.getRequestPath(request));
        String zoneId = IdentityZoneHolder.get().getId();
        ScimUser scimUserFromDb;
        try {
            scimUserFromDb = scimUserProvisioning.retrieve(id, zoneId);
        } catch (ScimResourceNotFoundException e) {
            // If the user does not exist, allow the operation to proceed (e.g., creation).
            return true;
        }

        // 4. Perform field‑by‑field validation using safe comparisons.
        if (!Objects.equals(scimUserFromDb.getPrimaryEmail(), scimUserFromRequest.getPrimaryEmail())) {
            return false;
        }
        if (!Objects.equals(scimUserFromDb.getUserName(), scimUserFromRequest.getUserName())) {
            return false;
        }
        if (scimUserFromDb.isVerified() != scimUserFromRequest.isVerified()) {
            return false;
        }
        if (scimUserFromDb.isActive() != scimUserFromRequest.isActive()) {
            return false;
        }
        if (!Objects.equals(scimUserFromDb.getOrigin(), scimUserFromRequest.getOrigin())) {
            return false;
        }

        return true;
    }

    // other methods
}
